using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using SimplexLawFirm.Data;using SimplexLawFirm.Infrastructure.Authorization;using SimplexLawFirm.Models;using SimplexLawFirm.Services;using SimplexLawFirm.Services.CurrentUser;
namespace SimplexLawFirm.Controllers;
[RequireSessionUser] public sealed class FeeDiscountController(ApplicationDbContext db,IFeeDiscountService service,ICurrentClientService clients):Controller{
 public async Task<IActionResult> Index(CancellationToken ct){var role=HttpContext.Session.GetString("UserRole");if(role=="Client"){var c=await clients.GetAsync(ct);if(c is null)return Forbid();return View(await db.FeeDiscountRequests.Include(x=>x.Invoice).Where(x=>x.ClientId==c.Id).ToListAsync(ct));}if(role is "Director" or "Admin")return View(await db.FeeDiscountRequests.Include(x=>x.Invoice).Include(x=>x.Client).OrderByDescending(x=>x.CreatedAtUtc).ToListAsync(ct));return Forbid();}
 [RequireSessionRole("Client")] public async Task<IActionResult> Create(int invoiceId,CancellationToken ct){var c=await clients.GetAsync(ct);if(c is null)return Forbid();var invoice=await db.Invoices.SingleOrDefaultAsync(x=>x.Id==invoiceId&&x.ClientId==c.Id&&!x.IsPaid,ct);return invoice is null?NotFound():View(invoice);}
 [HttpPost,RequireSessionRole("Client")] public async Task<IActionResult> Create(int invoiceId,decimal proposedAmount,string reason,CancellationToken ct){var c=await clients.GetAsync(ct);if(c is null)return Forbid();try{await service.RequestAsync(invoiceId,c.Id,proposedAmount,reason,ct);TempData["Success"]="Discount request recorded.";}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Details(int id,CancellationToken ct){var item=await db.FeeDiscountRequests.Include(x=>x.Invoice).Include(x=>x.Client).SingleOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return NotFound();var role=HttpContext.Session.GetString("UserRole");if(role=="Client"&&(await clients.GetAsync(ct))?.Id!=item.ClientId)return Forbid();if(role is not ("Client" or "Director" or "Admin"))return Forbid();return View(item);}
 [HttpPost] public async Task<IActionResult> Decide(int id,FeeDiscountStatus status,decimal? counterOfferAmount,string reason,CancellationToken ct){if(HttpContext.Session.GetString("UserRole") is not("Director"or"Admin"))return Forbid();try{await service.DecideAsync(id,HttpContext.Session.GetInt32("UserId")!.Value,status,counterOfferAmount,reason,ct);}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Details),new{id});}}
